from build import save
rows=[
(391,['奥特兰笔记任务物完成销毁；克文图斯探索乌服诺斯已接但先做十环刺杀。第九环sss引导任务杀下位神安东尼克，天使方也刺山德鲁。主角做30余极效虚无；赵岚馨订19号新星票，还有5天。视频示安禁咒与死亡天幕围城。'],['任务次序明确，战争待玩家行动。'],['双向刺杀和地下威胁如何影响战争？'],23818,23879),
(392,['十人进要塞，主角推泄露论坛刺杀情报会使己方对称加难而不报。命牛仔故踩陷阱试火箭雨冰环，亡灵巫师以骨牢救；依据十人须齐推NPC会救。'],['低代价测试防御以准备敌区。'],['公平同步加难尚未系统验证。'],23883,23947),
(393,['糖果观察萧自然对话引任务而敬佩。山德鲁说明三小时赐力、给地图；双方各中对方净化/诅咒剩不到1成，约各派十刺客且守卫最多30，第十环杀对方十贼。主角报黑暗之主潜地下要塞，山德鲁稳军继续赌攻城。'],['超强目标可行条件明确；PVE接后续PVP。'],[],23951,23997),
(394,['仪式连冥界，萧克服精神幻火，其他9虚脱后皆赐力十倍余。获伪装宝石10、十码10分钟隔结界、专家100%瞬回20每人2；项链暗力遭查，预先串供缴获物且镇定获准入城。'],['三小时倒计时启动，临时超常属性非永久。'],[],24001,24064),
(395,['战时圣光城闭商设工事，神圣殿堂奉泰尔摩斯。另一十盗贼赴要塞；萧找后园假山避炮塔潜入，十人分搜且发现后不独攻，遇60超阶守卫。'],['对称双线同时推进。'],[],24068,24102),
(396,['安东尼克与两女子私下调情，偷听索哈多数日后复活耶罗征恩泽斯，安入假山地底圣殿。萧推黑暗方勾结，找不到机关，清后园等其出。杀超阶得圣御腿换装，瞬进500%3秒；约旧腿2万给柠檬，待交易。'],['私德反差和潜藏政治背叛相接；新腿备关键战术。'],['索哈多耶罗具体身份未此处证实。'],24106,24170),
(397,['同职十贼改独杀归己/共获竞价。萧51，一小时清30卫藏尸，等10分安出。集控被闪烁抗拒瞬发群攻压退，萧新腿瞬进合龙翔禁法和凿击终于控住、打1/5，却触圣光守护6秒脱控。'],['引导不等于轻易胜利。'],['主角感觉有人窥视尚未确认。'],24174,24270),
(398,['扇火火海迫全队各用1专家瞬回，萧被冰，队友救而牛仔死。萧暗影克制脱冰搏命，耗一次涅槃复活以死亡自爆90余万伤，安余不足20万，糖果接指挥收尾。'],['主角复活只剩最后1次；强敌残血仍未杀。'],[],24274,24339),
(399,['6队友先后死，萧火凤涅槃属性+50%，召幽灵比蒙堵院门，余成员打安；龙翔禁法接小鬼凤舞终结，8万荣耀1.2万功勋。四人逃，比蒙守门死。萧看萧翎入假山地道；另一队刺山德鲁败死5散伙。'],['刺杀第九环击杀完成但未交奖；跨书人物明确露面。'],['萧翎地下任务结果只是萧御估计。'],24343,24416),
(400,['回要塞由祭坛复活6阵亡者，不损经验且分击杀收益。得神言下位神器副手杖与匕首；萧提PB，众退让，萧仍出50万、淘汰圣言匕首待分，装备神言匕。'],['全十人复齐，友情不取消报酬；复活代价被任务机制补偿。'],[],24420,24476),
(401,['圣言匕首12万给糖果，合神言匕50万62万分9人。神言副手杖200万由风野垫付给9人，萧购拟赠赵。交第九环得20万荣3万功200万经验+1000血、53级、每人史诗；萧披风30万卖宿命。报地下情报全队再2万荣。接第十坐标追杀，六队分行动。'],['共同战利品支付兑现；第十环已接未完成。'],[],24480,24540),
(402,['萧独战刷荣耀，新神言倍击体现；勋章仍准将被误判但实际准帅。三敌将军/准将联攻，萧以龙翔、控制、位移逐个杀后隐走，围观震惊。'],['实力展示与任务间歇相接。'],[],24544,24607),
(403,['赵岚馨海底礁石用梦魇球形AOE、海怪高经验低血，约10倍速升52，榜2；萧53榜1刺刀50第13。任务3后宿命妖孽被月白杀，萧去迎；任务6。比蒙探隐共享视野先发现月白但偷袭被其预感挡，月白51将军。'],['同伴速练有独立方法；第十环并非全为附送。'],[],24611,24671),
(404,['月白被禁回城、队败惩罚欲搏生，识萧强敌，说明对队有坏事成员但未展开。双方反手背刺速度破解、躲闪对控；萧后发锁定争尾时隙上五诅咒，月白仍疾风逃，追战开始。'],['失败队员仍有技术尊严。'],[],24675,24734),
(405,['萧赶月白入比蒙埋伏，逼出影子战士与精灵隐匿（需15探隐），主角无法透。借此预习刺刀影子，开启暗影克制免控，认准暗处本体。'],['月白影子操控生疏，不能推为刺刀强度。'],[],24738,24798),
(406,['比蒙冲撞致盲、萧裂爆终杀月白，史诗匕内部竞。其余9/10，末敌往南逃，糖果等追下午才杀齐。萧看非法票选视频，投蜗牛；见萧翎泰坦/石像鬼/蛇视频自估再战3成，收敛轻敌。远见高伤法师。'],['十目标已杀齐待交；高手对照压低膨胀。'],['视频句将萧翎误写萧御，需保留辨主体。'],24802,24854),
(407,['法师是萧翎；双方友善切磋且各藏比蒙/泰坦等主力。恶魔瞳破隐，石像鬼免物控挡突进；萧用能量牙刺魔控钻空近身，萧翎恐惧将出。'],['跨阵营朋友切磋有约束，非全力生死战。'],[],24858,24930),
(408,['能量爆满每天一次回100能量，裂爆先击萧翎瘫7秒、自己恐惧3秒，先醒停手。萧翎认输、萧御说不算因双方未尽力。交十环追刺得6万荣等，再换元帅勋前已晋元帅54；总十环队长加奖升55。换雪熊野性肩旧匿迹肩30万卖柠。十人解散互留友情，已还风野钱余300万，逛拍卖。'],['十环主线真正全奖与团队离别完成；乌服诺斯尚待。'],[],24934,25004),
(409,['裁缝大宗师增使60格包降价，买10供二人各5共各300格，公会供高药与20能量爆满。赵54。晚战刺刀赔率1:15对1:1.1，赵代双方押1亿萧占半，风野拟临末押20亿。'],['经济协作扩大竞技社会压力；备异星物资。'],['风野20亿还只是计划。'],25008,25096),
(410,['猴子50、卖装攒200万押萧并经引荐入风野公会，生活改善；柠橘共押800万，糖果嘴硬实押500万。萧实际领元帅勋力30%换准将20%。十余万观众，刺刀不败声势，双方登台未战。'],['旧援助对象回归报信任；最后决战待开始。'],[],25100,25171),
]
d={
'worldbuilding':[['引导为三小时临时十倍余属性，对方神级降至一成，双方守卫上限30；它给可行性并未消除战术难度。','fact',[393,23965,23975],[394,24033,24050],[397,24218,24243]],['神言杖是副手下位神器可再持一杖；神言匕概率倍击，圣言旧匕非同名同物。','fact',[400,24449,24459],[401,24480,24503]],['市场供给因裁缝大宗师普及与廉料令60格包跌价，装备阶位亦有随自身技能成长贬值。','fact',[396,24158,24166],[409,25008,25012]],['能量爆满每日一次补100，可把能量不足转为一回合资源决策。','fact',[408,24934,24942]]],
'characters':[['糖果从敬佩、接指挥、让竞到口头不下注却私下500万，关系转变由一连串行动而非突然表白体现。','fact',[393,23961,23964],[398,24336,24338],[400,24465,24471],[410,25128,25140]],['赵岚馨独立开发海底梦魇速练，非全程只陪伴主角；押注回应共同贫困又承载恋人承诺。','fact',[403,24615,24625],[409,25075,25087]],['月白败有任务惩罚装备差、队内失误和操影生疏，不等于无能；敌视角保有自尊与绝处拼搏。','fact',[404,24675,24689],[405,24746,24753],[406,24803,24805]]],
'plot':[['对称刺杀先PVE神级竞速，再PVP追杀失败队，战争结果因玩家行动分叉。','fact',[393,23965,23978],[399,24412,24416],[408,24953,24966]],['刺刀前用月白的影子作预习，既兑现第十任务又预告主决战技术难题。','inference',[405,24762,24779],[406,24803,24805],[410,25159,25171]],['新得瞬进腿随即补近身窗口，旧装备转队友，升级同时改变资源关系。','inference',[396,24158,24166],[397,24247,24253]]],
'style':[['战斗以技能短行、血量百分比、伤害与冷却交替推进；控制快感屡被免疫、触发护盾和援军打断。','inference',[397,24247,24267],[398,24278,24318],[399,24378,24395]],['安私德被谴“伪君子”又被羡慕艳福，女性被物化的叙述是源作价值张力，应审视而非当创作规范。','inference',[396,24109,24127]],['围观惊叹和财富规模放大爽感，需警惕重复震惊压过人物选择。','inference',[402,24595,24606],[409,25050,25085]]],
'narrative':[['论坛消息告密会同步加难是萧御与糖果推断，非系统确认；山德鲁本就知道对刺计划。','fact',[392,23901,23910],[393,23971,23978]],['安勾结地下方先为偷听推断，401主角报告获奖励但未揭索哈多耶罗全部身份。','fact',[396,24121,24127],[401,24521,24526]],['跨书萧翎入地道被亲眼见，任务完成和再战三成胜率则萧御估计；406视频主体局部误名。','fact',[399,24403,24407],[406,24841,24845]]],
'dialogue':[['“实力不足”自然引NPC给引导条件，再由糖果观察点出主角任务对话能力；兼推进线索与他人态度。','inference',[393,23960,23968]],['切磋前双方约隐藏醒目召唤，停杀后互认未尽力，语言给胜负以条件而非全书战力排名。','inference',[407,24869,24876],[408,24944,24949]],['解散中沉默、玩笑与糖果不道别回望形成各自表达，避免全员同一哭别语气。','inference',[408,24959,24995]]],
'pacing':[['清30卫一小时、等待十分钟后扩完整神级战；高奖励结算分两次，使“击杀”与“任务完成”各有兑现。','inference',[397,24185,24201],[401,24507,24518],[408,24953,24979]],['任务后野战横扫的无敌感，紧接月白、萧翎两个强敌校正，再推刺刀终局，强弱对照免单一膨胀。','inference',[402,24595,24607],[404,24691,24719],[406,24839,24846]],['下注与旧友回归在决战前拉长准备，压力由钱、名誉与私人信任逐层累积。','inference',[409,25075,25096],[410,25109,25141]]],
'themes':[['刺杀依复活、牺牲、接指挥与最后一击分给小鬼；领导贡献显著却非独自打完。','fact',[398,24313,24338],[399,24354,24403]],['共同稀有奖励里友谊不取消公平，主角仍付50万和200万而非把队员退让当免费占有。','fact',[400,24460,24474],[401,24485,24503]],['399批炫耀失败者，400又承认运气路线和技能关键，404补队内失误；道德化评判需与实际败因区分。','inference',[399,24412,24416],[400,24426,24428],[404,24675,24689]]],
'continuity':[['幽灵比蒙399守门死亡，403再可召出；此处只记录召唤续用，不虚构未给的复生过程/代价。','fact',[399,24401,24409],[403,24649,24654]],['萧御408晋55与元帅、410才实际领换元帅勋；402佩准将导致他人误认不等于降衔。','fact',[402,24554,24556],[408,24963,24974],[410,25143,25148]],['391去新星后一句称去母星；393困军外围一处写邪恶联盟、407回忆地道进入者误称萧御，均记源文疑误不另造事件。','fact',[391,23857,23861],[393,23988,23990],[407,24858,24860]],['401圣言12万加神言匕合计62万证明实际按50万，主角最初提出60万未成为最终付款。','fact',[400,24471,24474],[401,24485,24495]]],
}
c=[dict(key='xiao-yu',name='萧御',aliases=[],summary='50阶段升55、元帅并实际换勋。自爆涅槃后仅剩1复活；神言匕已装备、神言副手杖买给赵未在410交，圣御腿与雪熊肩更换。',goals=['先完十环再探乌服诺斯','晚场挑战刺刀','19号赴新星'],changes=['以自爆承担领队决策成本','任务全奖后解散十人','承认萧翎藏实力而收敛轻敌'],relationships=['赵岚馨恋人同押1亿','风野垫款已还、供药和拟押20亿','糖果由敌意到敬重'],knowledge=['获地下假山入口位置并告山德鲁','月白影子仅预习不代表刺刀水平'],source_anomalies=['外套称准将与实际元帅分开','406视频主体误名需按上下文辨'],evidence=[[398,24313,24327],[401,24489,24503],[408,24963,25000],[409,25075,25096]]),dict(key='yuebai',name='月白',aliases=[],summary='51将军精灵贼、失败刺山德鲁队领袖；击宿命妖孽，具敏锐感知、影子与精灵隐匿，但被萧比蒙致盲裂爆杀。',goals=['生存避免再掉级失顶尖资格'],changes=['由失败后求生到承认对手强并搏命'],relationships=['刺杀队受队内两人坏事之说，未列明','与萧互相认强敌'],knowledge=['意识主脑坐标追杀及回城被禁'],source_anomalies=[],evidence=[[403,24628,24669],[404,24676,24691],[405,24746,24782],[406,24803,24819]]),dict(key='tangguo',name='堕落的糖果',aliases=[],summary='十贼强者、原有敌意转敬佩；主角自爆后主动催收尾，竞12万圣言匕、私押500万。',goals=['完成任务','保有独立高手尊严'],changes=['与众熟络','承认主角领队价值仍爱面子'],relationships=['萧御朋友及竞争者','柠檬等协作队友'],knowledge=['赞同对称公平推断但仍非系统证实'],source_anomalies=[],evidence=[[391,23831,23834],[393,23961,23964],[398,24336,24338],[410,25128,25140]]),dict(key='zhao-lanxin',name='赵岚馨',aliases=[],summary='海族水法恋人，梦魇海底球形AOE礁石速练由48追至54；订新星票，愿共担贫困，代押1亿。',goals=['陪萧探乌服诺斯','与萧赴新星'],changes=['独创练级方案实现等级追赶'],relationships=['萧御明确女友','被猴子柠檬称嫂'],knowledge=['神言杖拟赠已告她晚上给，410未实际交付'],source_anomalies=[],evidence=[[391,23857,23865],[403,24615,24625],[409,25026,25087],[410,25108,25127]]),dict(key='houzi',name='猴子',aliases=[],summary='旧受助者至50，靠高难任务卖装攒200万、气色与生活改善，押萧赢并加入风野公会。',goals=['自主游戏谋生与成长'],changes=['从街头混混经历走向能自立玩家'],relationships=['感激萧御引路','接受风野邀请'],knowledge=[],source_anomalies=[],evidence=[[410,25109,25118]])]
